#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

static unsigned char failed[117650];
static unsigned char nextMask[36];

static int encodeRow(const char* row) {
    int code = 0;
    for (int i = 0; row[i] != '\0'; ++i) code = code * 7 + (row[i] - 'A' + 1);
    return code;
}

static bool dfs(const char* row, int len);

static bool buildUpper(const char* row, int len, char* upper, int i) {
    if (i == len - 1) return dfs(upper, len - 1);
    int idx = (row[i] - 'A') * 6 + (row[i + 1] - 'A');
    unsigned char mask = nextMask[idx];
    for (int bit = 0; bit < 6; ++bit) {
        if (mask & (1u << bit)) {
            upper[i] = (char)('A' + bit);
            if (buildUpper(row, len, upper, i + 1)) return true;
        }
    }
    return false;
}

static bool dfs(const char* row, int len) {
    if (len == 1) return true;
    int code = encodeRow(row);
    if (failed[code]) return false;
    for (int i = 0; i < len - 1; ++i) {
        int idx = (row[i] - 'A') * 6 + (row[i + 1] - 'A');
        if (nextMask[idx] == 0) {
            failed[code] = 1;
            return false;
        }
    }
    char upper[6];
    if (buildUpper(row, len, upper, 0)) return true;
    failed[code] = 1;
    return false;
}

static void collectStrings(const char* s, char** out, int* count) {
    int n = 0;
    for (int i = 0; s[i] != '\0'; ) {
        if (s[i] == '\"') {
            int start = ++i;
            while (s[i] != '\0' && s[i] != '\"') ++i;
            int len = i - start;
            out[n] = (char*)malloc((size_t)len + 1);
            memcpy(out[n], s + start, (size_t)len);
            out[n][len] = '\0';
            ++n;
            if (s[i] == '\"') ++i;
        } else {
            ++i;
        }
    }
    *count = n;
}

int main(void) {
    char line[10000];
    if (!fgets(line, sizeof(line), stdin)) return 0;

    char* values[217];
    int count = 0;
    collectStrings(line, values, &count);
    if (count == 0) return 0;

    memset(failed, 0, sizeof(failed));
    memset(nextMask, 0, sizeof(nextMask));
    for (int i = 1; i < count; ++i) {
        int idx = (values[i][0] - 'A') * 6 + (values[i][1] - 'A');
        nextMask[idx] |= (unsigned char)(1u << (values[i][2] - 'A'));
    }

    printf("%s\n", dfs(values[0], (int)strlen(values[0])) ? "true" : "false");

    for (int i = 0; i < count; ++i) free(values[i]);
    return 0;
}

