class Solution {
    bool dfs(const string& row, const vector<vector<char>>& nexts, unordered_set<string>& failed) {
        if (row.size()==1) return true;
        if (failed.count(row)) return false;
        vector<const vector<char>*> choices;
        for (size_t i=0;i+1<row.size();i++) {
            const auto& v = nexts[(row[i]-'A')*6 + (row[i+1]-'A')];
            if (v.empty()) { failed.insert(row); return false; }
            choices.push_back(&v);
        }
        string upper(row.size()-1, 'A');
        function<bool(size_t)> build = [&](size_t i) {
            if (i==upper.size()) return dfs(upper,nexts,failed);
            for (char ch : *choices[i]) {
                upper[i]=ch;
                if (build(i+1)) return true;
            }
            return false;
        };
        if (build(0)) return true;
        failed.insert(row);
        return false;
    }
public:
    bool pyramidTransition(string bottom, vector<string>& allowed) {
        vector<vector<char>> nexts(36);
        for (const string& p : allowed) nexts[(p[0]-'A')*6 + (p[1]-'A')].push_back(p[2]);
        unordered_set<string> failed;
        return dfs(bottom,nexts,failed);
    }
};

