class Solution {
    public boolean pyramidTransition(String bottom, List<String> allowed) {
        @SuppressWarnings("unchecked")
        List<Character>[] nexts = new ArrayList[36];
        for (int i=0;i<36;i++) nexts[i] = new ArrayList<>();
        for (String p : allowed) {
            int idx = (p.charAt(0)-'A')*6 + (p.charAt(1)-'A');
            nexts[idx].add(p.charAt(2));
        }
        Set<String> failed = new HashSet<>();
        return dfs(bottom, nexts, failed);
    }

    private boolean dfs(String row, List<Character>[] nexts, Set<String> failed) {
        if (row.length() == 1) return true;
        if (failed.contains(row)) return false;
        List<List<Character>> choices = new ArrayList<>();
        for (int i=0;i<row.length()-1;i++) {
            List<Character> c = nexts[(row.charAt(i)-'A')*6 + (row.charAt(i+1)-'A')];
            if (c.isEmpty()) { failed.add(row); return false; }
            choices.add(c);
        }
        char[] upper = new char[row.length()-1];
        if (build(0, upper, choices, nexts, failed)) return true;
        failed.add(row);
        return false;
    }

    private boolean build(int i, char[] upper, List<List<Character>> choices, List<Character>[] nexts, Set<String> failed) {
        if (i == upper.length) return dfs(new String(upper), nexts, failed);
        for (char ch : choices.get(i)) {
            upper[i] = ch;
            if (build(i+1, upper, choices, nexts, failed)) return true;
        }
        return false;
    }
}

